// ============ PRODUCT DATA ============
const products = [
  {
    id: 'p1',
    name: 'Heritage Wool Overcoat',
    category: 'Outerwear',
    price: 489,
    rating: 4.8,
    tag: 'New',
    palette: ['#2a2a2e', '#0f0f12', '#c9a66b'],
    shape: 'coat',
  },
  {
    id: 'p2',
    name: 'Brushed Cashmere Crew',
    category: 'Knitwear',
    price: 215,
    oldPrice: 285,
    rating: 4.7,
    tag: 'Sale',
    palette: ['#3a2f24', '#1a1410', '#c9a66b'],
    shape: 'sweater',
  },
  {
    id: 'p3',
    name: 'Pleated Wool Trouser',
    category: 'Trousers',
    price: 195,
    rating: 4.6,
