    tag: 'Bestseller',
    palette: ['#2d241b', '#100c08', '#c9a66b'],
    shape: 'shoe',
  },
  {
    id: 'p5',
    name: 'Hand-Poured Cedar Candle',
    category: 'Home',
    price: 48,
    rating: 4.8,
    palette: ['#1c1c22', '#0a0a0e', '#c9a66b'],
    shape: 'candle',
  },
  {
    id: 'p6',
    name: 'Linen Throw Blanket',
    category: 'Home',
    price: 165,
    oldPrice: 195,
    rating: 4.5,
    tag: 'Sale',
    palette: ['#2a2520', '#14110e'],
