  },
  {
    id: 'p7',
    name: 'Merino Beanie',
    category: 'Accessories',
    price: 65,
    rating: 4.6,
    palette: ['#252530', '#10101a'],
    shape: 'beanie',
  },
  {
    id: 'p8',
    name: 'Leather Bifold Wallet',
    category: 'Accessories',
    price: 145,
    rating: 4.7,
    tag: 'New',
    palette: ['#2d201a', '#120c08', '#c9a66b'],
    shape: 'wallet',
  },
];

// ============ SVG SHAPES (decorative product art) ============
function productSvg(p) {
  const [c1, c2, accent = '#c9a66b'] = p.palette;
  const gid = `g-${p.id}`;
  const shapes = {
    coat: `<path d="M50 80 L80 40 L160 40 L190 80 L200 280 L40 280 Z" fill="url(#${gid})" stroke="#3a3a40" stroke-width="1"/>
           <path d="M120 40 L120 280" stroke="#1a1a1d" stroke-width="2"/>
           <circle cx="120" cy="100" r="3" fill="${accent}"/>
           <circle cx="120" cy="135" r="3" fill="${accent}"/>
           <circle cx="120" cy="170" r="3" fill="${accent}"/>
           <circle cx="120" cy="205" r="3" fill="${accent}"/>`,
    sweater: `<path d="M40 100 L80 60 L160 60 L200 100 L190 130 L160 110 L160 280 L80 280 L80 110 L50 130 Z" fill="url(#${gid})" stroke="#3a3a40"/>
              <path d="M80 130 L160 130" stroke="#1a1a1d" stroke-width="0.5" opacity="0.5"/>
              <path d="M80 160 L160 160" stroke="#1a1a1d" stroke-width="0.5" opacity="0.5"/>`,
    trouser: `<path d="M70 40 L170 40 L165 280 L130 280 L125 150 L115 150 L110 280 L75 280 Z" fill="url(#${gid})" stroke="#3a3a40"/>
              <path d="M120 50 L120 140" stroke="#1a1a1d" stroke-width="1"/>`,
    shoe: `<ellipse cx="120" cy="200" rx="90" ry="30" fill="url(#${gid})" stroke="#3a3a40"/>
           <path d="M40 200 Q40 140 100 130 L180 140 Q210 150 210 200 Z" fill="url(#${gid})" stroke="#3a3a40"/>
           <path d="M100 145 L170 150" stroke="${accent}" stroke-width="1" opacity="0.6"/>
           <path d="M105 160 L175 165" stroke="${accent}" stroke-width="1" opacity="0.6"/>`,
    candle: `<rect x="80" y="80" width="80" height="180" rx="4" fill="url(#${gid})" stroke="#3a3a40"/>
             <ellipse cx="120" cy="80" rx="40" ry="6" fill="#3a3a40"/>
             <path d="M120 60 L118 80 L122 80 Z" fill="${accent}"/>
             <ellipse cx="120" cy="50" rx="6" ry="12" fill="${accent}" opacity="0.5"/>`,
    blanket: `<rect x="40" y="60" width="160" height="200" rx="4" fill="url(#${gid})" stroke="#3a3a40"/>
              <path d="M60 100 L180 100 M60 130 L180 130 M60 160 L180 160 M60 190 L180 190 M60 220 L180 220" stroke="${accent}" stroke-width="0.5" opacity="0.3"/>
              <path d="M40 220 Q60 210 80 220 L80 260 L40 260 Z" fill="${c2}"/>`,
    beanie: `<path d="M60 180 Q60 80 120 80 Q180 80 180 180 L180 200 L60 200 Z" fill="url(#${gid})" stroke="#3a3a40"/>
             <rect x="55" y="195" width="130" height="25" fill="${c2}" stroke="#3a3a40"/>
             <circle cx="120" cy="65" r="12" fill="${c1}" stroke="#3a3a40"/>`,
    wallet: `<rect x="40" y="100" width="160" height="120" rx="6" fill="url(#${gid})" stroke="#3a3a40"/>
             <path d="M40 160 L200 160" stroke="#1a1a1d" stroke-width="1"/>
             <rect x="140" y="180" width="40" height="3" fill="${accent}" opacity="0.6"/>
             <rect x="140" y="190" width="30" height="3" fill="${accent}" opacity="0.4"/>`,
  };
  return `
    <svg viewBox="0 0 240 300" preserveAspectRatio="xMidYMid meet" width="100%" height="100%" aria-hidden="true">
      <defs>
        <linearGradient id="${gid}" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stop-color="${c1}"/>
          <stop offset="1" stop-color="${c2}"/>
        </linearGradient>
      </defs>
      ${shapes[p.shape] || ''}
    </svg>
  `;
}

function productCard(p) {
  const li = document.createElement('li');
  li.className = 'product';
  const tagClass = p.tag === 'Sale' ? 'product-tag product-tag-sale' : 'product-tag';
  const tagHtml = p.tag ? `<span class="${tagClass}">${p.tag}</span>` : '';
  const oldPriceHtml = p.oldPrice ? `<span class="product-price-old">$${p.oldPrice}</span>` : '';
  li.innerHTML = `
    <div class="product-art">
      ${tagHtml}
      <button type="button" class="product-fav" aria-label="Save ${p.name} to favorites" aria-pressed="false">
        <svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M12 21s-7-4.5-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6c-2.5 4.5-9.5 9-9.5 9Z"/>
        </svg>
      </button>
      ${productSvg(p)}
    </div>
    <div class="product-info">
      <p class="product-cat">${p.category}</p>
      <h3 class="product-name"><a href="#">${p.name}</a></h3>
      <div class="product-price-row">
        <div>
          <span class="product-price">$${p.price}</span>${oldPriceHtml}
        </div>
        <span class="product-rating" aria-label="Rated ${p.rating} out of 5">
          <span class="star" aria-hidden="true">★</span>${p.rating}
        </span>
      </div>
    </div>
  `;
  return li;
}

// ============ INIT ============
document.addEventListener('DOMContentLoaded', () => {
  // Render products
  const grid = document.getElementById('productGrid');
  if (grid) {
    products.forEach(p => grid.appendChild(productCard(p)));
  }

  // Favorite toggle
  document.addEventListener('click', e => {
    const btn = e.target.closest('.product-fav');
    if (!btn) return;
    const pressed = btn.getAttribute('aria-pressed') === 'true';
    btn.setAttribute('aria-pressed', String(!pressed));
  });

  // Mobile menu toggle
  const menuBtn = document.getElementById('menuToggle');
  const mobileNav = document.getElementById('mobileNav');
  if (menuBtn && mobileNav) {
    menuBtn.addEventListener('click', () => {
      const open = menuBtn.getAttribute('aria-expanded') === 'true';
      menuBtn.setAttribute('aria-expanded', String(!open));
      menuBtn.setAttribute('aria-label', open ? 'Open menu' : 'Close menu');
      mobileNav.hidden = open;
    });
    mobileNav.addEventListener('click', e => {
      if (e.target.tagName === 'A') {
        menuBtn.setAttribute('aria-expanded', 'false');
        menuBtn.setAttribute('aria-label', 'Open menu');
        mobileNav.hidden = true;
      }
    });
  }

  // Countdown timer (24h rolling)
  const countdownEl = document.getElementById('countdown');
  if (countdownEl) {
    const endsAt = Date.now() + 1000 * 60 * 60 * 23 + 1000 * 60 * 47; // ~23h 47m
    const tick = () => {
      const ms = Math.max(0, endsAt - Date.now());
      const h = Math.floor(ms / 3600000);
      const m = Math.floor((ms % 3600000) / 60000);
      const s = Math.floor((ms % 60000) / 1000);
      const pad = n => String(n).padStart(2, '0');
      countdownEl.textContent = `${pad(h)}:${pad(m)}:${pad(s)}`;
    };
    tick();
    setInterval(tick, 1000);
  }

  // Newsletter form
  const form = document.getElementById('newsletterForm');
  if (form) {
    const status = document.getElementById('emailHelp');
    const input = document.getElementById('emailInput');
    form.addEventListener('submit', e => {
      e.preventDefault();
      const value = (input.value || '').trim();
      const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
      if (!valid) {
        status.textContent = 'Please enter a valid email address.';
        status.className = 'form-status is-error';
        input.setAttribute('aria-invalid', 'true');
        input.focus();
        return;
      }
      input.removeAttribute('aria-invalid');
      status.textContent = `Thanks — we'll be in touch at ${value}.`;
      status.className = 'form-status is-success';
      form.reset();
    });
    input.addEventListener('input', () => {
      if (input.getAttribute('aria-invalid') === 'true') {
        input.removeAttribute('aria-invalid');
        status.textContent = '';
        status.className = 'form-status';
      }
    });
  }
});

