+  --bg-2: #16161a;
+  --bg-3: #1d1d22;
+  --bg-4: #25252b;
+  --line: #2a2a30;
+  --line-strong: #3a3a42;
+  --text-0: #f4f3ef;
+  --text-1: #d6d4cc;
+  --text-2: #9c9a92;
+  --text-3: #6f6d65;
+  --accent: #c9a66b;
+  --accent-strong: #d9b87d;
+  --accent-soft: rgba(201, 166, 107, 0.14);
+  --danger: #e36b6b;
+  --success: #7ec488;
+  --radius-sm: 6px;
+  --radius-md: 12px;
+  --radius-lg: 20px;
+  --shadow-1: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 24px rgba(0, 0, 0, 0.35);
+  --shadow-2: 0 2px 4px rgba(0, 0, 0, 0.5), 0 24px 60px rgba(0, 0, 0, 0.45);
+  --container: 1200px;
+  --header-h: 72px;
+  --font-sans: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
+  --font-serif: 'Fraunces', Georgia, 'Times New Roman', serif;
+}
+
+/* ============ RESET ============ */
+*, *::before, *::after { box-sizing: border-box; }
+html { -webkit-text-size-adjust: 100%; }
+body {
+  margin: 0;
+  background: var(--bg-0);
+  color: var(--text-1);
+  font-family: var(--font-sans);
+  font-size: 16px;
+  line-height: 1.55;
+  -webkit-font-smoothing: antialiased;
+  text-rendering: optimizeLegibility;
+}
+img, svg { display: block; max-width: 100%; }
+ul { list-style: none; padding: 0; margin: 0; }
+a { color: inherit; text-decoration: none; }
+button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
+
+/* ============ A11Y ============ */
+.visually-hidden {
+  position: absolute !important;
+  width: 1px; height: 1px;
+  padding: 0; margin: -1px;
+  overflow: hidden; clip: rect(0,0,0,0);
+  white-space: nowrap; border: 0;
+}
+.skip-link {
+  position: absolute;
+  left: 12px; top: -100px;
+  background: var(--accent);
+  color: #1a1306;
+  padding: 10px 14px;
+  border-radius: var(--radius-sm);
+  font-weight: 600;
+  z-index: 1000;
+  transition: top 0.18s ease;
+}
+.skip-link:focus { top: 12px; outline: none; }
+
+:focus-visible {
+  outline: 2px solid var(--accent-strong);
+  outline-offset: 3px;
+  border-radius: 4px;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after { animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; }
+}
+
+/* ============ LAYOUT ============ */
+.container {
+  width: min(100% - 40px, var(--container));
+  margin-inline: auto;
+}
+
+.section { padding: 88px 0; }
+@media (max-width: 720px) { .section { padding: 56px 0; } }
+
+.section-head {
+  display: flex;
+  align-items: end;
+  justify-content: space-between;
+  gap: 24px;
+  margin-bottom: 32px;
+  flex-wrap: wrap;
+}
+
+/* ============ TYPE ============ */
+h1, h2, h3 {
+  color: var(--text-0);
+  font-family: var(--font-serif);
+  font-weight: 600;
+  letter-spacing: -0.01em;
+  line-height: 1.1;
+  margin: 0;
+}
+h2 { font-size: clamp(1.75rem, 3vw, 2.5rem); }
+h3 { font-size: 1.15rem; line-height: 1.3; }
+p { margin: 0; }
+
+.eyebrow {
+  display: inline-block;
+  font-size: 0.75rem;
+  font-weight: 600;
+  letter-spacing: 0.18em;
+  text-transform: uppercase;
+  color: var(--text-2);
+  margin: 0 0 12px;
+}
+.eyebrow-accent { color: var(--accent); }
+
+em { font-style: italic; color: var(--accent-strong); font-family: var(--font-serif); }
+
+.link-arrow {
+  color: var(--text-0);
+  font-weight: 500;
+  border-bottom: 1px solid var(--line-strong);
+  padding-bottom: 4px;
+  transition: border-color 0.2s, color 0.2s;
+}
+.link-arrow:hover { color: var(--accent); border-color: var(--accent); }
+
+/* ============ BUTTONS ============ */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  padding: 13px 22px;
+  border-radius: 999px;
+  font-weight: 600;
+  font-size: 0.92rem;
+  letter-spacing: 0.01em;
+  border: 1px solid transparent;
+  transition: transform 0.1s ease, background 0.2s, color 0.2s, border-color 0.2s;
+  min-height: 44px;
+}
+.btn:active { transform: translateY(1px); }
+.btn-primary { background: var(--accent); color: #1a1306; }
+.btn-primary:hover { background: var(--accent-strong); }
+.btn-ghost { color: var(--text-0); border-color: var(--line-strong); }
+.btn-ghost:hover { border-color: var(--text-2); background: var(--bg-2); }
+
+.icon-btn {
+  position: relative;
+  width: 42px; height: 42px;
+  display: inline-grid;
+  place-items: center;
+  border-radius: 50%;
+  color: var(--text-0);
+  transition: background 0.2s;
+}
+.icon-btn:hover { background: var(--bg-3); }
+.cart-count {
+  position: absolute;
+  top: 4px; right: 2px;
+  background: var(--accent);
+  color: #1a1306;
+  font-size: 0.65rem;
+  font-weight: 700;
+  min-width: 18px; height: 18px;
+  border-radius: 50%;
+  display: grid;
+  place-items: center;
+  padding: 0 4px;
+  border: 2px solid var(--bg-1);
+}
+
+/* ============ HEADER ============ */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 100;
+  background: rgba(10, 10, 12, 0.85);
+  backdrop-filter: blur(14px);
+  -webkit-backdrop-filter: blur(14px);
+  border-bottom: 1px solid var(--line);
+}
+.header-inner {
+  display: flex;
+  align-items: center;
+  gap: 24px;
+  height: var(--header-h);
+}
+.brand {
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  font-family: var(--font-serif);
+  font-weight: 700;
+  color: var(--text-0);
+  font-size: 1rem;
+  letter-spacing: 0.18em;
+}
+.brand-mark { color: var(--accent); font-size: 1.25rem; }
+
+.primary-nav { margin-inline: auto; }
+.primary-nav ul { display: flex; gap: 4px; }
+.primary-nav a {
+  display: inline-block;
+  padding: 10px 14px;
+  border-radius: var(--radius-sm);
+  font-size: 0.92rem;
+  color: var(--text-1);
+  font-weight: 500;
+  transition: color 0.2s, background 0.2s;
+}
+.primary-nav a:hover { color: var(--text-0); background: var(--bg-2); }
+
+.header-actions { display: flex; align-items: center; gap: 4px; }
+.menu-toggle { display: none; }
+
+.mobile-nav {
+  border-top: 1px solid var(--line);
+  background: var(--bg-1);
+  padding: 12px 20px 16px;
+}
+.mobile-nav ul { display: flex; flex-direction: column; gap: 2px; }
+.mobile-nav a {
+  display: block;
+  padding: 12px 4px;
+  font-size: 1rem;
+  color: var(--text-0);
+  border-bottom: 1px solid var(--line);
+}
+
+@media (max-width: 880px) {
+  .primary-nav { display: none; }
+  .menu-toggle { display: inline-grid; }
+}
+
+/* ============ HERO ============ */
+.hero {
+  position: relative;
+  overflow: hidden;
+  padding: 80px 0 100px;
+  border-bottom: 1px solid var(--line);
+}
+.hero-bg { position: absolute; inset: 0; pointer-events: none; }
+.hero-orb {
+  position: absolute;
+  border-radius: 50%;
+  filter: blur(80px);
+  opacity: 0.45;
+}
+.hero-orb-1 {
+  width: 480px; height: 480px;
+  top: -120px; right: -100px;
+  background: radial-gradient(circle, var(--accent) 0%, transparent 70%);
+  opacity: 0.18;
+}
+.hero-orb-2 {
+  width: 380px; height: 380px;
+  bottom: -120px; left: -80px;
+  background: radial-gradient(circle, #4a3a8a 0%, transparent 70%);
+  opacity: 0.25;
+}
+.hero-grid {
+  position: absolute; inset: 0;
+  background-image:
+    linear-gradient(to right, rgba(255,255,255,0.025) 1px, transparent 1px),
+    linear-gradient(to bottom, rgba(255,255,255,0.025) 1px, transparent 1px);
+  background-size: 60px 60px;
+  mask-image: radial-gradient(ellipse at center, black 30%, transparent 80%);
+}
+.hero-inner {
+  position: relative;
+  display: grid;
+  grid-template-columns: 1.4fr 1fr;
+  gap: 60px;
+  align-items: center;
+}
+.hero-title {
+  font-family: var(--font-serif);
+  font-size: clamp(2.5rem, 5.5vw, 4.5rem);
+  font-weight: 600;
+  line-height: 1.05;
+  letter-spacing: -0.02em;
+  margin: 8px 0 20px;
+  color: var(--text-0);
+}
+.hero-lede {
+  font-size: 1.1rem;
+  color: var(--text-2);
+  max-width: 48ch;
+  margin-bottom: 32px;
+}
+.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }
+.hero-stats {
+  margin: 48px 0 0;
+  display: grid;
+  grid-template-columns: repeat(3, auto);
+  gap: 28px;
+  padding-top: 28px;
+  border-top: 1px solid var(--line);
+  max-width: 540px;
+}
+.hero-stats div { display: flex; flex-direction: column; gap: 4px; }
+.hero-stats dt { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.12em; color: var(--text-3); margin: 0; }
+.hero-stats dd { margin: 0; font-size: 0.95rem; color: var(--text-0); font-weight: 500; }
+
+.hero-card {
+  background: linear-gradient(160deg, var(--bg-3), var(--bg-1));
+  border: 1px solid var(--line-strong);
+  border-radius: var(--radius-lg);
+  padding: 24px;
+  box-shadow: var(--shadow-2);
+  position: relative;
+  transform: rotate(1.5deg);
+}
+.hero-card-inner {
+  background: var(--bg-0);
+  border-radius: var(--radius-md);
+  padding: 20px;
+  border: 1px solid var(--line);
+}
+.hero-tag {
+  display: inline-block;
+  font-size: 0.7rem;
+  letter-spacing: 0.15em;
+  text-transform: uppercase;
+  color: var(--accent);
+  background: var(--accent-soft);
+  padding: 6px 10px;
+  border-radius: 999px;
+  margin-bottom: 16px;
+}
+.hero-product-art {
+  aspect-ratio: 5/6;
+  background: linear-gradient(180deg, var(--bg-2), var(--bg-1));
+  border-radius: var(--radius-sm);
+  display: grid;
+  place-items: center;
+  padding: 20px;
+}
+.hero-product-meta {
+  display: flex;
+  justify-content: space-between;
+  align-items: baseline;
+  margin-top: 16px;
+}
+.hero-product-name { color: var(--text-0); font-weight: 500; }
+.hero-product-price { color: var(--accent); font-weight: 600; font-family: var(--font-serif); font-size: 1.1rem; }
+
+@media (max-width: 880px) {
+  .hero-inner { grid-template-columns: 1fr; gap: 48px; }
+  .hero-card { max-width: 320px; margin: 0 auto; }
+  .hero-stats { grid-template-columns: 1fr 1fr; gap: 20px; }
+}
+
+/* ============ CATEGORIES ============ */
+.categories {
+  padding: 32px 0;
+  border-bottom: 1px solid var(--line);
+  background: var(--bg-1);
+}
+.cat-list {
+  display: flex;
+  gap: 10px;
+  overflow-x: auto;
+  scrollbar-width: thin;
+  padding-bottom: 4px;
+}
+.cat-pill {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  padding: 10px 18px;
+  border: 1px solid var(--line-strong);
+  border-radius: 999px;
+  color: var(--text-1);
+  font-size: 0.9rem;
+  font-weight: 500;
+  white-space: nowrap;
+  background: var(--bg-2);
+  transition: border-color 0.2s, color 0.2s, background 0.2s;
+}
+.cat-pill:hover { border-color: var(--accent); color: var(--text-0); background: var(--bg-3); }
+.cat-pill span { color: var(--accent); }
+
+/* ============ PRODUCT GRID ============ */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 24px;
+}
+@media (max-width: 1000px) { .product-grid { grid-template-columns: repeat(3, 1fr); } }
+@media (max-width: 720px)  { .product-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; } }
+@media (max-width: 420px)  { .product-grid { grid-template-columns: 1fr; } }
+
+.product {
+  background: var(--bg-1);
+  border: 1px solid var(--line);
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: border-color 0.2s, transform 0.2s;
+}
+.product:hover { border-color: var(--line-strong); transform: translateY(-2px); }
+.product-art {
+  aspect-ratio: 4/5;
+  background: var(--bg-2);
+  position: relative;
+  overflow: hidden;
+}
+.product-art svg { width: 100%; height: 100%; }
+.product-tag {
+  position: absolute;
+  top: 12px; left: 12px;
+  font-size: 0.68rem;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  background: var(--bg-0);
+  color: var(--text-0);
+  padding: 5px 9px;
+  border-radius: 4px;
+  font-weight: 600;
+  border: 1px solid var(--line);
+}
+.product-tag-sale { background: var(--accent); color: #1a1306; border-color: var(--accent); }
+.product-fav {
+  position: absolute;
+  top: 10px; right: 10px;
+  width: 36px; height: 36px;
+  border-radius: 50%;
+  background: rgba(10,10,12,0.6);
+  color: var(--text-0);
+  display: grid;
+  place-items: center;
+  backdrop-filter: blur(6px);
+  transition: background 0.2s, color 0.2s;
+}
+.product-fav:hover { background: var(--bg-0); color: var(--accent); }
+.product-fav[aria-pressed="true"] { color: var(--accent); }
+.product-info {
+  padding: 16px 18px 18px;
+  display: flex;
+  flex-direction: column;
+  gap: 4px;
+  flex: 1;
+}
+.product-cat { font-size: 0.72rem; letter-spacing: 0.14em; text-transform: uppercase; color: var(--text-3); }
+.product-name { color: var(--text-0); font-weight: 500; font-size: 0.98rem; line-height: 1.3; }
+.product-name a { color: inherit; }
+.product-name a::after { content: ''; position: absolute; inset: 0; }
+.product-info { position: relative; }
+.product-price-row {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  gap: 12px;
+  margin-top: 8px;
+}
+.product-price {
+  color: var(--text-0);
+  font-family: var(--font-serif);
+  font-size: 1.1rem;
+  font-weight: 600;
+}
+.product-price-old {
+  color: var(--text-3);
+  text-decoration: line-through;
+  font-size: 0.88rem;
+  margin-left: 6px;
+  font-family: var(--font-sans);
+  font-weight: 400;
+}
+.product-rating {
+  display: inline-flex;
+  align-items: center;
+  gap: 4px;
+  font-size: 0.82rem;
+  color: var(--text-2);
+}
+.product-rating .star { color: var(--accent); }
+
+/* ============ DEALS ============ */
+.deals-section {
+  background:
+    radial-gradient(ellipse at top right, rgba(201, 166, 107, 0.05), transparent 60%),
+    var(--bg-0);
+}
+.countdown {
+  display: inline-flex;
+  align-items: center;
+  gap: 12px;
+  padding: 10px 18px;
+  background: var(--bg-2);
+  border: 1px solid var(--line-strong);
+  border-radius: 999px;
+}
+.countdown-label { font-size: 0.78rem; color: var(--text-2); text-transform: uppercase; letter-spacing: 0.12em; }
+.countdown-value {
+  color: var(--accent);
+  font-family: var(--font-serif);
+  font-weight: 600;
+  font-variant-numeric: tabular-nums;
+  font-size: 1.05rem;
+}
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr;
+  grid-template-rows: 1fr 1fr;
+  gap: 20px;
+}
+.deal {
+  position: relative;
+  background: var(--bg-1);
+  border: 1px solid var(--line);
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: border-color 0.2s, transform 0.2s;
+}
+.deal:hover { border-color: var(--line-strong); transform: translateY(-2px); }
+.deal-feature {
+  grid-row: 1 / span 2;
+  display: grid;
+  grid-template-rows: 1fr auto;
+}
+.deal-art { aspect-ratio: 4/3; background: var(--bg-2); }
+.deal-feature .deal-art { aspect-ratio: auto; min-height: 280px; }
+.deal-art-sm { aspect-ratio: 2/1; }
+.deal-content { padding: 24px; display: flex; flex-direction: column; gap: 10px; align-items: flex-start; }
+.deal-feature .deal-content { padding: 32px; gap: 14px; }
+.deal-desc { color: var(--text-2); font-size: 0.92rem; }
+.deal-badge {
+  position: absolute;
+  top: 16px; left: 16px;
+  background: var(--accent);
+  color: #1a1306;
+  font-weight: 700;
+  font-size: 0.85rem;
+  padding: 6px 12px;
+  border-radius: 999px;
+  letter-spacing: 0.04em;
+  z-index: 2;
+}
+.deal-badge-alt { background: var(--bg-0); color: var(--accent); border: 1px solid var(--accent); }
+
+@media (max-width: 880px) {
+  .deals-grid { grid-template-columns: 1fr; grid-template-rows: auto; }
+  .deal-feature { grid-row: auto; }
+  .deal-feature .deal-art { min-height: 200px; }
+}
+
+/* ============ EDITORIAL ============ */
+.editorial { background: var(--bg-1); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr 1fr;
+  grid-template-rows: 1fr 1fr;
+  gap: 20px;
+}
+.editorial-card {
+  background: var(--bg-2);
+  border: 1px solid var(--line);
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  transition: border-color 0.2s, transform 0.2s;
+}
+.editorial-card:hover { border-color: var(--line-strong); transform: translateY(-2px); }
+.editorial-feature { grid-row: 1 / span 2; }
+.editorial-link {
+  display: flex;
+  flex-direction: column;
+  height: 100%;
+  color: inherit;
+}
+.editorial-art { aspect-ratio: 16/10; background: var(--bg-3); overflow: hidden; }
+.editorial-feature .editorial-art { aspect-ratio: auto; flex: 1; min-height: 280px; }
+.editorial-card h3 { padding: 0 22px 22px; color: var(--text-0); }
+.editorial-feature h3 { font-size: 1.6rem; padding: 0 28px 12px; }
+.editorial-feature p { padding: 0 28px 28px; color: var(--text-2); }
+.editorial-card:not(.editorial-feature) h3 { font-size: 1.05rem; }
+.editorial-meta {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  padding: 18px 22px 10px;
+  font-size: 0.78rem;
+  color: var(--text-3);
+  letter-spacing: 0.04em;
+}
+.editorial-feature .editorial-meta { padding: 22px 28px 8px; }
+.tag {
+  color: var(--accent);
+  text-transform: uppercase;
+  letter-spacing: 0.14em;
+  font-weight: 600;
+  font-size: 0.72rem;
+}
+.dot { color: var(--text-3); }
+
+@media (max-width: 1000px) {
+  .editorial-grid { grid-template-columns: 1fr 1fr; }
+  .editorial-feature { grid-column: 1 / -1; grid-row: auto; }
+  .editorial-feature .editorial-art { min-height: 240px; }
+}
+@media (max-width: 600px) {
+  .editorial-grid { grid-template-columns: 1fr; }
+}
+
+/* ============ NEWSLETTER ============ */
+.newsletter {
+  background:
+    radial-gradient(ellipse at bottom left, rgba(201, 166, 107, 0.06), transparent 60%),
+    var(--bg-0);
+  border-top: 1px solid var(--line);
+}
+.newsletter-inner {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 60px;
+  align-items: center;
+}
+.newsletter h2 { max-width: 18ch; }
+.newsletter-lede { color: var(--text-2); margin-top: 12px; }
+.newsletter-form {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+  align-items: center;
+  background: var(--bg-2);
+  padding: 8px;
+  border-radius: 999px;
+  border: 1px solid var(--line-strong);
+  position: relative;
+}
+.newsletter-form input[type="email"] {
+  flex: 1;
+  min-width: 200px;
+  background: transparent;
+  border: 0;
+  color: var(--text-0);
+  font: inherit;
+  padding: 12px 18px;
+  outline: none;
+}
+.newsletter-form input::placeholder { color: var(--text-3); }
+.newsletter-form input:focus-visible { outline: 2px solid var(--accent-strong); outline-offset: 2px; border-radius: 999px; }
+.form-status {
+  position: absolute;
+  top: calc(100% + 8px);
+  left: 18px;
+  font-size: 0.85rem;
+  color: var(--text-2);
+  min-height: 1.2em;
+}
+.form-status.is-error { color: var(--danger); }
+.form-status.is-success { color: var(--success); }
+
+@media (max-width: 800px) {
+  .newsletter-inner { grid-template-columns: 1fr; gap: 32px; }
+}
