:root {
  --bg-0: #0a0a0c;
  --bg-1: #111114;
  --bg-2: #16161a;
  --bg-3: #1d1d22;
  --bg-4: #25252b;
  --line: #2a2a30;
  --line-strong: #3a3a42;
  --text-0: #f4f3ef;
  --text-1: #d6d4cc;
  --text-2: #9c9a92;
  --text-3: #6f6d65;
  --accent: #c9a66b;
  --accent-strong: #d9b87d;
  --accent-soft: rgba(201, 166, 107, 0.14);
  --danger: #e36b6b;
  --success: #7ec488;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-1: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 24px rgba(0, 0, 0, 0.35);
  --shadow-2: 0 2px 4px rgba(0, 0, 0, 0.5), 0 24px 60px rgba(0, 0, 0, 0.45);
  --container: 1200px;
  --header-h: 72px;
  --font-sans: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  --font-serif: 'Fraunces', Georgia, 'Times New Roman', serif;
}

/* ============ RESET ============ */
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg-0);
  color: var(--text-1);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
img, svg { display: block; max-width: 100%; }
ul { list-style: none; padding: 0; margin: 0; }
a { color: inherit; text-decoration: none; }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }

/* ============ A11Y ============ */
.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}
.skip-link {
  position: absolute;
  left: 12px; top: -100px;
  background: var(--accent);
  color: #1a1306;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  z-index: 1000;
  transition: top 0.18s ease;
}
.skip-link:focus { top: 12px; outline: none; }

:focus-visible {
  outline: 2px solid var(--accent-strong);
  outline-offset: 3px;
  border-radius: 4px;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; }
}

/* ============ LAYOUT ============ */
.container {
  width: min(100% - 40px, var(--container));
  margin-inline: auto;
}

.section { padding: 88px 0; }
@media (max-width: 720px) { .section { padding: 56px 0; } }

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}

/* ============ TYPE ============ */
h1, h2, h3 {
  color: var(--text-0);
  font-family: var(--font-serif);
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.1;
  margin: 0;
}
h2 { font-size: clamp(1.75rem, 3vw, 2.5rem); }
h3 { font-size: 1.15rem; line-height: 1.3; }
p { margin: 0; }

.eyebrow {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-2);
  margin: 0 0 12px;
}
.eyebrow-accent { color: var(--accent); }

em { font-style: italic; color: var(--accent-strong); font-family: var(--font-serif); }

.link-arrow {
  color: var(--text-0);
  font-weight: 500;
  border-bottom: 1px solid var(--line-strong);
  padding-bottom: 4px;
  transition: border-color 0.2s, color 0.2s;
}
.link-arrow:hover { color: var(--accent); border-color: var(--accent); }

/* ============ BUTTONS ============ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 13px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.92rem;
  letter-spacing: 0.01em;
  border: 1px solid transparent;
  transition: transform 0.1s ease, background 0.2s, color 0.2s, border-color 0.2s;
  min-height: 44px;
}
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--accent); color: #1a1306; }
.btn-primary:hover { background: var(--accent-strong); }
.btn-ghost { color: var(--text-0); border-color: var(--line-strong); }
.btn-ghost:hover { border-color: var(--text-2); background: var(--bg-2); }

.icon-btn {
  position: relative;
  width: 42px; height: 42px;
  display: inline-grid;
  place-items: center;
  border-radius: 50%;
  color: var(--text-0);
  transition: background 0.2s;
}
.icon-btn:hover { background: var(--bg-3); }
.cart-count {
  position: absolute;
  top: 4px; right: 2px;
  background: var(--accent);
  color: #1a1306;
  font-size: 0.65rem;
  font-weight: 700;
  min-width: 18px; height: 18px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  padding: 0 4px;
  border: 2px solid var(--bg-1);
}

/* ============ HEADER ============ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(10, 10, 12, 0.85);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 24px;
  height: var(--header-h);
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-serif);
  font-weight: 700;
  color: var(--text-0);
  font-size: 1rem;
  letter-spacing: 0.18em;
}
.brand-mark { color: var(--accent); font-size: 1.25rem; }

.primary-nav { margin-inline: auto; }
.primary-nav ul { display: flex; gap: 4px; }
.primary-nav a {
  display: inline-block;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.92rem;
  color: var(--text-1);
  font-weight: 500;
  transition: color 0.2s, background 0.2s;
}
.primary-nav a:hover { color: var(--text-0); background: var(--bg-2); }

.header-actions { display: flex; align-items: center; gap: 4px; }
.menu-toggle { display: none; }

.mobile-nav {
  border-top: 1px solid var(--line);
  background: var(--bg-1);
  padding: 12px 20px 16px;
}
.mobile-nav ul { display: flex; flex-direction: column; gap: 2px; }
.mobile-nav a {
  display: block;
  padding: 12px 4px;
  font-size: 1rem;
  color: var(--text-0);
  border-bottom: 1px solid var(--line);
}

@media (max-width: 880px) {
  .primary-nav { display: none; }
  .menu-toggle { display: inline-grid; }
}

/* ============ HERO ============ */
.hero {
  position: relative;
  overflow: hidden;
  padding: 80px 0 100px;
  border-bottom: 1px solid var(--line);
}
.hero-bg { position: absolute; inset: 0; pointer-events: none; }
.hero-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.45;
}
.hero-orb-1 {
  width: 480px; height: 480px;
  top: -120px; right: -100px;
  background: radial-gradient(circle, var(--accent) 0%, transparent 70%);
  opacity: 0.18;
}
.hero-orb-2 {
  width: 380px; height: 380px;
  bottom: -120px; left: -80px;
  background: radial-gradient(circle, #4a3a8a 0%, transparent 70%);
  opacity: 0.25;
}
.hero-grid {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(to right, rgba(255,255,255,0.025) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255,255,255,0.025) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse at center, black 30%, transparent 80%);
}
.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 60px;
  align-items: center;
}
.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 5.5vw, 4.5rem);
  font-weight: 600;
