  max-width: 48ch;
  margin-bottom: 32px;
}
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }
.hero-stats {
  margin: 48px 0 0;
  display: grid;
  grid-template-columns: repeat(3, auto);
  gap: 28px;
  padding-top: 28px;
  border-top: 1px solid var(--line);
  max-width: 540px;
}
.hero-stats div { display: flex; flex-direction: column; gap: 4px; }
.hero-stats dt { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.12em; color: var(--text-3); margin: 0; }
.hero-stats dd { margin: 0; font-size: 0.95rem; color: var(--text-0); font-weight: 500; }

.hero-card {
  background: linear-gradient(160deg, var(--bg-3), var(--bg-1));
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-lg);
  padding: 24px;
