  .hero-stats { grid-template-columns: 1fr 1fr; gap: 20px; }
}

/* ============ CATEGORIES ============ */
.categories {
  padding: 32px 0;
  border-bottom: 1px solid var(--line);
  background: var(--bg-1);
}
.cat-list {
  display: flex;
  gap: 10px;
