function productCard(p) {
  const li = document.createElement('li');
  li.className = 'product';
  const tagClass = p.tag === 'Sale' ? 'product-tag product-tag-sale' : 'product-tag';
  const tagHtml = p.tag ? `<span class="${tagClass}">${p.tag}</span>` : '';
  const oldPriceHtml = p.oldPrice ? `<span class="product-price-old">$${p.oldPrice}</span>` : '';
  li.innerHTML = `
    <div class="product-art">
      ${tagHtml}
      <button type="button" class="product-fav" aria-label="Save ${p.name} to favorites" aria-pressed="false">
        <svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2">
