  max-width: 48ch;
  margin-bottom: 32px;
}
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }
.hero-stats {
  margin: 48px 0 0;
  display: grid;
  grid-template-columns: repeat(3, auto);
  gap: 28px;
  padding-top: 28px;
  border-top: 1px solid var(--line);
  max-width: 540px;
}
.hero-stats div { display: flex; flex-direction: column; gap: 4px; }
.hero-stats dt { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.12em; color: var(--text-3); margin: 0; }
