  border: 1px solid var(--line);
}
.hero-tag {
  display: inline-block;
  font-size: 0.7rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent);
  background: var(--accent-soft);
  padding: 6px 10px;
  border-radius: 999px;
  margin-bottom: 16px;
}
.hero-product-art {
  aspect-ratio: 5/6;
  background: linear-gradient(180deg, var(--bg-2), var(--bg-1));
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  padding: 20px;
}
.hero-product-meta {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-top: 16px;
}
.hero-product-name { color: var(--text-0); font-weight: 500; }
.hero-product-price { color: var(--accent); font-weight: 600; font-family: var(--font-serif); font-size: 1.1rem; }

@media (max-width: 880px) {
  .hero-inner { grid-template-columns: 1fr; gap: 48px; }
  .hero-card { max-width: 320px; margin: 0 auto; }
  .hero-stats { grid-template-columns: 1fr 1fr; gap: 20px; }
}

/* ============ CATEGORIES ============ */
.categories {
  padding: 32px 0;
  border-bottom: 1px solid var(--line);
  background: var(--bg-1);
}
.cat-list {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  scrollbar-width: thin;
  padding-bottom: 4px;
}
.cat-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  color: var(--text-1);
  font-size: 0.9rem;
  font-weight: 500;
  white-space: nowrap;
  background: var(--bg-2);
  transition: border-color 0.2s, color 0.2s, background 0.2s;
}
.cat-pill:hover { border-color: var(--accent); color: var(--text-0); background: var(--bg-3); }
.cat-pill span { color: var(--accent); }

/* ============ PRODUCT GRID ============ */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
@media (max-width: 1000px) { .product-grid { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 720px)  { .product-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; } }
@media (max-width: 420px)  { .product-grid { grid-template-columns: 1fr; } }

.product {
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 0.2s, transform 0.2s;
}
.product:hover { border-color: var(--line-strong); transform: translateY(-2px); }
.product-art {
  aspect-ratio: 4/5;
  background: var(--bg-2);
  position: relative;
  overflow: hidden;
}
.product-art svg { width: 100%; height: 100%; }
.product-tag {
  position: absolute;
  top: 12px; left: 12px;
  font-size: 0.68rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--bg-0);
  color: var(--text-0);
  padding: 5px 9px;
  border-radius: 4px;
  font-weight: 600;
  border: 1px solid var(--line);
}
.product-tag-sale { background: var(--accent); color: #1a1306; border-color: var(--accent); }
.product-fav {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(10,10,12,0.6);
  color: var(--text-0);
  display: grid;
  place-items: center;
  backdrop-filter: blur(6px);
  transition: background 0.2s, color 0.2s;
}
.product-fav:hover { background: var(--bg-0); color: var(--accent); }
.product-fav[aria-pressed="true"] { color: var(--accent); }
.product-info {
  padding: 16px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}
.product-cat { font-size: 0.72rem; letter-spacing: 0.14em; text-transform: uppercase; color: var(--text-3); }
.product-name { color: var(--text-0); font-weight: 500; font-size: 0.98rem; line-height: 1.3; }
.product-name a { color: inherit; }
.product-name a::after { content: ''; position: absolute; inset: 0; }
.product-info { position: relative; }
.product-price-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-top: 8px;
}
.product-price {
  color: var(--text-0);
  font-family: var(--font-serif);
  font-size: 1.1rem;
  font-weight: 600;
}
.product-price-old {
  color: var(--text-3);
  text-decoration: line-through;
  font-size: 0.88rem;
  margin-left: 6px;
  font-family: var(--font-sans);
  font-weight: 400;
}
.product-rating {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.82rem;
  color: var(--text-2);
}
.product-rating .star { color: var(--accent); }

/* ============ DEALS ============ */
.deals-section {
  background:
    radial-gradient(ellipse at top right, rgba(201, 166, 107, 0.05), transparent 60%),
    var(--bg-0);
}
.countdown {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 10px 18px;
  background: var(--bg-2);
  border: 1px solid var(--line-strong);
  border-radius: 999px;
}
.countdown-label { font-size: 0.78rem; color: var(--text-2); text-transform: uppercase; letter-spacing: 0.12em; }
.countdown-value {
  color: var(--accent);
  font-family: var(--font-serif);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  font-size: 1.05rem;
}

.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 20px;
}
.deal {
  position: relative;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 0.2s, transform 0.2s;
}
.deal:hover { border-color: var(--line-strong); transform: translateY(-2px); }
.deal-feature {
  grid-row: 1 / span 2;
  display: grid;
  grid-template-rows: 1fr auto;
}
.deal-art { aspect-ratio: 4/3; background: var(--bg-2); }
.deal-feature .deal-art { aspect-ratio: auto; min-height: 280px; }
.deal-art-sm { aspect-ratio: 2/1; }
.deal-content { padding: 24px; display: flex; flex-direction: column; gap: 10px; align-items: flex-start; }
.deal-feature .deal-content { padding: 32px; gap: 14px; }
.deal-desc { color: var(--text-2); font-size: 0.92rem; }
.deal-badge {
  position: absolute;
  top: 16px; left: 16px;
  background: var(--accent);
  color: #1a1306;
  font-weight: 700;
  font-size: 0.85rem;
  padding: 6px 12px;
  border-radius: 999px;
  letter-spacing: 0.04em;
  z-index: 2;
}
.deal-badge-alt { background: var(--bg-0); color: var(--accent); border: 1px solid var(--accent); }

@media (max-width: 880px) {
  .deals-grid { grid-template-columns: 1fr; grid-template-rows: auto; }
  .deal-feature { grid-row: auto; }
  .deal-feature .deal-art { min-height: 200px; }
}

/* ============ EDITORIAL ============ */
.editorial { background: var(--bg-1); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 20px;
}
.editorial-card {
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color 0.2s, transform 0.2s;
}
.editorial-card:hover { border-color: var(--line-strong); transform: translateY(-2px); }
.editorial-feature { grid-row: 1 / span 2; }
.editorial-link {
  display: flex;
  flex-direction: column;
  height: 100%;
  color: inherit;
}
.editorial-art { aspect-ratio: 16/10; background: var(--bg-3); overflow: hidden; }
.editorial-feature .editorial-art { aspect-ratio: auto; flex: 1; min-height: 280px; }
.editorial-card h3 { padding: 0 22px 22px; color: var(--text-0); }
.editorial-feature h3 { font-size: 1.6rem; padding: 0 28px 12px; }
.editorial-feature p { padding: 0 28px 28px; color: var(--text-2); }
.editorial-card:not(.editorial-feature) h3 { font-size: 1.05rem; }
.editorial-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 18px 22px 10px;
  font-size: 0.78rem;
  color: var(--text-3);
  letter-spacing: 0.04em;
}
.editorial-feature .editorial-meta { padding: 22px 28px 8px; }
.tag {
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-weight: 600;
  font-size: 0.72rem;
}
.dot { color: var(--text-3); }

@media (max-width: 1000px) {
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-feature { grid-column: 1 / -1; grid-row: auto; }
  .editorial-feature .editorial-art { min-height: 240px; }
}
@media (max-width: 600px) {
  .editorial-grid { grid-template-columns: 1fr; }
}

/* ============ NEWSLETTER ============ */
.newsletter {
  background:
    radial-gradient(ellipse at bottom left, rgba(201, 166, 107, 0.06), transparent 60%),
    var(--bg-0);
  border-top: 1px solid var(--line);
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.newsletter h2 { max-width: 18ch; }
.newsletter-lede { color: var(--text-2); margin-top: 12px; }
.newsletter-form {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  background: var(--bg-2);
  padding: 8px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  position: relative;
}
.newsletter-form input[type="email"] {
  flex: 1;
  min-width: 200px;
  background: transparent;
  border: 0;
  color: var(--text-0);
  font: inherit;
  padding: 12px 18px;
  outline: none;
}
.newsletter-form input::placeholder { color: var(--text-3); }
.newsletter-form input:focus-visible { outline: 2px solid var(--accent-strong); outline-offset: 2px; border-radius: 999px; }
.form-status {
  position: absolute;
  top: calc(100% + 8px);
  left: 18px;
  font-size: 0.85rem;
  color: var(--text-2);
  min-height: 1.2em;
}
.form-status.is-error { color: var(--danger); }
.form-status.is-success { color: var(--success); }

@media (max-width: 800px) {
  .newsletter-inner { grid-template-columns: 1fr; gap: 32px; }
}

/* ============ FOOTER ============ */
.site-footer {
  background: var(--bg-1);
  border-top: 1px solid var(--line);
  padding: 64px 0 24px;
  color: var(--text-2);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 48px;
  border-bottom: 1px solid var(--line);
}
.footer-brand p { margin-top: 16px; font-size: 0.92rem; max-width: 32ch; }
.brand-footer { font-size: 1rem; }
.footer-heading {
  font-family: var(--font-sans);
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--text-0);
  margin: 0 0 18px;
}
.site-footer ul { display: flex; flex-direction: column; gap: 10px; }
.site-footer a {
  font-size: 0.92rem;
  color: var(--text-2);
  transition: color 0.2s;
}
.site-footer a:hover { color: var(--text-0); }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 24px;
  flex-wrap: wrap;
  gap: 12px;
}
.legal { display: flex; gap: 20px; }
.legal a { font-size: 0.85rem; }

@media (max-width: 800px) {
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

/* ============ FORCED COLORS ============ */
@media (forced-colors: active) {
  .btn, .cat-pill, .product, .deal, .editorial-card, .countdown, .newsletter-form {
    border: 1px solid CanvasText;
  }
  .btn-primary { background: ButtonFace; color: ButtonText; }
  :focus-visible { outline: 2px solid Highlight; }
}
